\begin{aligned}
\sigma_S(a\approx b)&=\sigma_{\mathsf I}(a)\approx\sigma_{\mathsf I}(b),&
\sigma_S(a\not\approx b)&=\sigma_{\mathsf I}(a)\not\approx\sigma_{\mathsf I}(b),\\
\sigma_S(\ell\approx m)&=\sigma_{\mathsf L}(\ell)\approx\sigma_{\mathsf L}(m),&
\sigma_S(\ell\not\approx m)&=\sigma_{\mathsf L}(\ell)\not\approx\sigma_{\mathsf L}(m),
\end{aligned}

\mathsf R_{\mathsf{inst}}
=\{((C(a),C\sqsubseteq D),D(a)):C,D\in CE^{DL}_\Sigma,\ a\in N_{\operatorname{Ind}}\},
\quad
\mathsf R_{\neg}
=\{(((\neg C)(a),C(a)),\bot_\Sigma):C\in CE^{DL}_\Sigma,\ a\in N_{\operatorname{Ind}}\},

\mathsf R_{\sqcup L}
=\{(((C(a))),(C\sqcup D)(a)):C,D\in CE^{DL}_\Sigma,\ a\in N_{\operatorname{Ind}}\},
\quad
\mathsf R_{\sqcup R}
=\{(((D(a))),(C\sqcup D)(a)):C,D\in CE^{DL}_\Sigma,\ a\in N_{\operatorname{Ind}}\},

\mathsf R_{\sqcup E}
=\{(((C\sqcup D)(a),C\sqsubseteq E,D\sqsubseteq E),E(a)):
C,D,E\in CE^{DL}_\Sigma,\ a\in N_{\operatorname{Ind}}\},

\mathsf R_{\sqcap E1}
=\{((((C\sqcap D)(a))),C(a)):C,D\in CE^{DL}_\Sigma,\ a\in N_{\operatorname{Ind}}\},
\quad
\mathsf R_{\sqcap E2}
=\{((((C\sqcap D)(a))),D(a)):C,D\in CE^{DL}_\Sigma,\ a\in N_{\operatorname{Ind}}\},

\mathsf R_{\exists I}
=\{((R(a,b),C(b)),(\exists R.C)(a)):
R\in R_\Sigma,\ C\in CE^{DL}_\Sigma,\ a,b\in N_{\operatorname{Ind}}\},

\mathsf R_{\forall E}
=\{(((\forall R.C)(a),R(a,b)),C(b)):
R\in R_\Sigma,\ C\in CE^{DL}_\Sigma,\ a,b\in N_{\operatorname{Ind}}\},

\mathsf R_{\ge}
=
\left\{
\left(
\bigl((R(a,b_i),C(b_i))_{i<n},(b_i\not\approx b_j)_{i<j<n}\bigr),
(\ge n\,R.C)(a)
\right):
\begin{array}{l}
n\in\mathbb N,\ R\in R_\Sigma,\ C\in CE^{DL}_\Sigma,\\
a,b_0,\ldots,b_{n-1}\in N_{\operatorname{Ind}}
\end{array}
\right\},

\mathsf R_{\le}
=
\left\{
\left(
\bigl((\le n\,R.C)(a),(R(a,b_i),C(b_i))_{i\le n},
(b_i\not\approx b_j)_{i<j\le n}\bigr),
\bot_\Sigma
\right):
\begin{array}{l}
n\in\mathbb N,\ R\in R_\Sigma,\ C\in CE^{DL}_\Sigma,\\
a,b_0,\ldots,b_n\in N_{\operatorname{Ind}}
\end{array}
\right\}.

\mathsf R_{\mathsf{chain}}
=
\left\{
\left(
\bigl(\operatorname{SubObjectPropertyOf}((R_0,\ldots,R_{m-1}),S),
(R_i(a_i,a_{i+1}))_{i<m}\bigr),
S(a_0,a_m)
\right):
\begin{array}{l}
m>0,\ R_0,\ldots,R_{m-1},S\in R_\Sigma,\\
a_0,\ldots,a_m\in N_{\operatorname{Ind}}
\end{array}
\right\},

\mathsf R_{\mathsf{funcO}}
=\{((\operatorname{FunctionalObjectProperty}(R),R(a,b),R(a,c)),b\approx c):
R\in R_\Sigma,\ a,b,c\in N_{\operatorname{Ind}}\},

\mathsf R_{\mathsf{ifuncO}}
=\{((\operatorname{InverseFunctionalObjectProperty}(R),R(b,a),R(c,a)),b\approx c):
R\in R_\Sigma,\ a,b,c\in N_{\operatorname{Ind}}\},

\mathsf R_{\mathsf{subD}}
=\{((\operatorname{SubDataPropertyOf}(q,s),q(a,\ell)),s(a,\ell)):
q,s\in N_{\operatorname{DataProp}},\ a\in N_{\operatorname{Ind}},\ \ell\in N_{\operatorname{Lit}}\},

\mathsf R_{\mathsf{funcD}}
=\{((\operatorname{FunctionalDataProperty}(q),q(a,\ell),q(a,m)),\ell\approx m):
q\in N_{\operatorname{DataProp}},\ a\in N_{\operatorname{Ind}},\ \ell,m\in N_{\operatorname{Lit}}\},

\mathsf R_{\mathsf{disjD}}
=\{((\operatorname{DisjointDataProperties}(q,s),q(a,\ell),s(a,\ell)),\bot_\Sigma):
q,s\in N_{\operatorname{DataProp}},\ a\in N_{\operatorname{Ind}},\ \ell\in N_{\operatorname{Lit}}\},

\mathsf R_{\approx D}
=\{((a\approx b,q(a,\ell)),q(b,\ell)):
q\in N_{\operatorname{DataProp}},\ a,b\in N_{\operatorname{Ind}},\ \ell\in N_{\operatorname{Lit}}\}.
